declare(strict_types=1);require_once '../config/database.php';$token=trim($_GET['token']??'');$message='Invalid or expired verification link.';$ok=false;if($token!==''){$s=$pdo->prepare("SELECT user_id FROM email_verification_tokens WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW() LIMIT 1");$s->execute([hash('sha256',$token)]);$id=(int)$s->fetchColumn();if($id){$pdo->beginTransaction();try{$pdo->prepare("UPDATE customer_profiles SET email_verified_at=NOW() WHERE user_id=?")->execute([$id]);$pdo->prepare("UPDATE email_verification_tokens SET used_at=NOW() WHERE user_id=? AND used_at IS NULL")->execute([$id]);$pdo->commit();$ok=true;$message='Your email address has been verified.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();}}}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Email Verification | NBW</title><link rel="stylesheet" href="../assets/css/customer-auth-v3.css"></head><body class="auth-v3"><main class="auth-form-side"><div class="auth-card"><p class="auth-kicker">Email verification</p><h2><?=$ok?'Verified.':'Unable to verify.'?></h2><div class="auth-alert <?=$ok?'success':'error'?>"><?=htmlspecialchars($message)?></div><p class="auth-switch"><a href="login.php">Continue to sign in</a></p></div></main></body></html>